await run('compress-images','compress-pdf',[path.join(OUT,'jpg2pdf-images.pdf')],{before:async p=>{await p.waitForFunction(()=>document.querySelector('.est')?.textContent);},check:async b=>{if(b.length>=fs.statSync(path.join(OUT,'jpg2pdf-images.pdf')).size)throw new Error('not smaller');isPdf(b);return b.length+' bytes (input '+fs.statSync(path.join(OUT,'jpg2pdf-images.pdf')).size+')'}});
await run('protect','protect-pdf',['sample.pdf'],{opts:{pw:'s3cret',pw2:'s3cret'},check:async(b,fp)=>{if(!b.toString('latin1').includes('/Encrypt'))throw new Error('no /Encrypt');fs.copyFileSync(fp,path.join(OUT,'protected.pdf'));return 'encrypted'}});
await run('unlock','unlock-pdf',[path.join(OUT,'protected.pdf')],{opts:{pw:'s3cret'},check:async b=>{if(b.toString('latin1').includes('/Encrypt'))throw new Error('still encrypted');const n=await pages(b);return 'decrypted, '+n+' pages'}});
await run('unlock-wrongpw','unlock-pdf',[path.join(OUT,'protected.pdf')],{opts:{pw:'nope'},check:async b=>{throw new Error('should have failed')}}).then(()=>{const r=results[results.length-1];if(r&&r[1]==='unlock-wrongpw'&&r[0]==='FAIL'&&!/should have/.test(r[2])){r[0]='PASS';r[2]='correctly rejected: '+r[2].slice(0,60);}});
await run('sign','sign-pdf',['sample.pdf'],{before:async p=>{await p.waitForSelector('.preview canvas');await p.locator('.sigpad').scrollIntoViewIfNeeded();const pad=await p.locator('.sigpad').boundingBox();await p.mouse.move(pad.x+20,pad.y+50);await p.mouse.down();for(let i=0;i<20;i++)await p.mouse.move(pad.x+20+i*12,pad.y+50+Math.sin(i)*30);await p.mouse.up();await p.selectOption('#pgsel','2');await p.waitForTimeout(300);await p.click('.preview canvas',{position:{x:100,y:300}});},check:async b=>{isPdf(b);const d=await PDFDocument.load(b);return 'signed, pages '+d.getPageCount()}});
await run('edit','edit-pdf',['sample.pdf'],{before:async p=>{await p.waitForSelector('.ppage canvas');await p.waitForTimeout(800);await p.locator('.play').evaluate(e=>{e.scrollIntoView({block:'start'});scrollBy(0,-120);});await p.waitForTimeout(300);const b=await p.locator('.play').boundingBox();await p.mouse.click(b.x+40,b.y+40);await p.keyboard.type('Hello – edited “ok”');await p.click('[data-m=white]');await p.locator('.play').evaluate(e=>{e.scrollIntoView({block:'start'});scrollBy(0,-120);});await p.waitForTimeout(300);const c=await p.locator('.play').boundingBox();await p.mouse.click(c.x+120,c.y+150);},check:async b=>{isPdf(b);return 'edited'}});
await run('pdf2word','pdf-to-word',['sample.pdf'],{check:async b=>{const z=await JSZip.loadAsync(b);const x=await z.file('word/document.xml').async('string');if(!x.includes('quick brown fox'))throw new Error('text missing');return (x.match(/<w:p>/g)||[]).length+' paragraphs'}});
await run('word2pdf','word-to-pdf',['sample.docx'],{check:async b=>{isPdf(b);return 'pages '+await pages(b)}});
await run('merge-ta','merge-pdf',['sample.pdf','second.pdf'],{lang:'ta/',check:async b=>'pages '+await pages(b)});
await run('rotate-hi','rotate-pdf',['second.pdf'],{lang:'hi/',check:async b=>'pages '+await pages(b)});
const {execFileSync}=require('child_process');const ptxt=(fp,a=[])=>execFileSync('pdftotext',[...a,fp,'-']).toString();
const tmpf=b=>{const fp=path.join(OUT,'tmp-'+Math.random().toString(36).slice(2)+'.pdf');fs.writeFileSync(fp,b);return fp;};
await run('organize-reorder','organize-pdf',['sample.pdf'],{before:async p=>{await p.waitForSelector('.thumb canvas');await p.evaluate(()=>{const th=document.querySelectorAll('.thumb');const dt=new DataTransfer();th[4].dispatchEvent(new DragEvent('dragstart',{bubbles:true,dataTransfer:dt}));th[0].dispatchEvent(new DragEvent('dragover',{bubbles:true,cancelable:true,dataTransfer:dt}));th[0].dispatchEvent(new DragEvent('drop',{bubbles:true,cancelable:true,dataTransfer:dt}));});await p.locator('.thumb').nth(1).locator('[data-a=d]').click();await p.locator('.thumb').nth(2).locator('[data-a=r]').click();},check:async(b,fp)=>{const t=ptxt(fp);const order=[...t.matchAll(/Sample page (\d)/g)].map(m=>m[1]).join('');const d=await PDFDocument.load(b);const rot=d.getPages().map(p=>p.getRotation().angle);if(order!=='5234'||rot[1]!==90)throw new Error('order '+order+' rot '+rot);return 'order '+order+', rot '+rot}});
